<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Camera,Clock,ShieldCheck} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import {useVintro} from '../composables/useVintro';const route=useRoute();const {state,updateQuote}=useVintro();const quote=computed(()=>state.quotes.find(q=>q.id===route.params.id)??state.quotes[0]);const action=ref<'Approved'|'Declined'|null>(null);const confirm=()=>{if(action.value)updateQuote(quote.value.id,action.value);action.value=null};const total=computed(()=>quote.value.labour+quote.value.parts.reduce((sum,p)=>sum+p.price,0))
</script>
<template><PageHeader title="Workshop quote" back="/quotes"/><div class="container-app max-w-3xl py-7"><div class="flex items-center justify-between"><div><p class="eyebrow">{{quote.workshop}}</p><h1 class="mt-2 text-2xl font-semibold">{{quote.service}}</h1></div><StatusBadge :status="quote.status"/></div><div class="mt-6 flex gap-3 rounded-2xl bg-amber-50 p-4 text-sm"><Clock :size="19" class="shrink-0 text-amber"/><p>Quote expires <strong>{{quote.expires}}</strong>. No work is approved until you confirm.</p></div><section class="card mt-5 p-5"><h2 class="section-title">Workshop recommendation</h2><p class="mt-3 text-sm leading-6 text-muted">{{quote.recommendation}}</p><button v-if="quote.photos" class="mt-4 flex items-center gap-2 rounded-xl bg-stone-100 px-4 py-3 text-sm font-medium"><Camera :size="17"/>View {{quote.photos}} workshop photos</button></section><section class="card mt-5 overflow-hidden"><div class="p-5"><h2 class="section-title">Quote details</h2></div><div class="divide-y border-t"><div class="flex justify-between px-5 py-4 text-sm"><span>Labour</span><strong class="nums">CHF {{quote.labour}}</strong></div><div v-for="p in quote.parts" class="flex justify-between px-5 py-4 text-sm"><span>{{p.name}}</span><strong class="nums">CHF {{p.price}}</strong></div><div class="flex justify-between bg-stone-50 px-5 py-5"><strong>Total</strong><strong class="nums text-xl">CHF {{total}}</strong></div></div></section><div class="mt-5 flex gap-3" v-if="quote.status==='Pending'"><button @click="action='Declined'" class="btn-secondary flex-1">Decline</button><button @click="action='Approved'" class="btn-primary flex-1">Approve work</button></div><div v-else class="mt-5 flex gap-3 rounded-2xl bg-emerald-50 p-5"><ShieldCheck :size="20" class="text-success"/><p class="text-sm">This quote is <strong>{{quote.status.toLowerCase()}}</strong>. The workshop can see your decision.</p></div></div><ConfirmDialog :open="!!action" @close="action=null" @confirm="confirm"><h2 class="text-xl font-semibold">{{action==='Approved'?'Approve this work?':'Decline this quote?'}}</h2><p class="mt-2 text-sm leading-6 text-muted">Your decision will be shared with {{quote.workshop}}. This remains a local prototype action.</p><template #confirm>{{action==='Approved'?'Approve work':'Decline quote'}}</template></ConfirmDialog></template>
